import AVFoundation
import DictationCore
import Foundation
import XCTest
@testable import Recognition

final class PublicSpeechAssetTests: XCTestCase {
    struct Fixture: Decodable { let id: String; let reference: String; let audioSeconds: Double }
    struct Result: Encodable {
        let id: String
        let reference: String
        let transcript: String
        let audioSeconds: Double
        let finalizationMilliseconds: Double
        let replayReleaseMilliseconds: Double
        let partialCountBeforeRelease: Int
        let firstPartialMilliseconds: Double?
        let partialCount: Int
        let final: Bool
    }

    func testRecordedHumanSpeechThroughProductionReplay() async throws {
        let env = ProcessInfo.processInfo.environment
        let root = URL(fileURLWithPath: try XCTUnwrap(env["POPTART_PUBLIC_SPEECH_PACK"]))
        let audio = URL(fileURLWithPath: try XCTUnwrap(env["POPTART_PUBLIC_SPEECH_AUDIO"]))
        let output = URL(fileURLWithPath: try XCTUnwrap(env["POPTART_PUBLIC_SPEECH_OUTPUT"]))
        let fixtures = try JSONDecoder().decode([Fixture].self,
            from: Data(contentsOf: audio.appendingPathComponent("fixtures.json")))
        XCTAssertEqual(fixtures.count, 16)
        let clock = UptimeMonotonicClock()
        let observations = PublicSpeechObservations(clock: clock)
        let service = try RecognitionService(modelLayout: .init(
            unifiedModelDirectory: root.appendingPathComponent("recognition/unified"),
            ctcModelDirectory: root.appendingPathComponent("recognition/ctc"),
            vadModelDirectory: root.appendingPathComponent("vad")),
            replaying: [0], sampleRate: 16_000, clock: clock,
            onEvent: { await observations.receive($0) })
        try await service.prepare()
        var results: [Result] = []
        for fixture in fixtures {
            let file = try AVAudioFile(forReading: audio.appendingPathComponent(fixture.id + ".wav"),
                commonFormat: .pcmFormatFloat32, interleaved: false)
            XCTAssertEqual(file.processingFormat.sampleRate, 16_000)
            XCTAssertEqual(file.processingFormat.channelCount, 1)
            let recording = try XCTUnwrap(AVAudioPCMBuffer(pcmFormat: file.processingFormat,
                frameCapacity: AVAudioFrameCount(file.length)))
            try file.read(into: recording)
            let samples = Array(UnsafeBufferPointer(start: try XCTUnwrap(recording.floatChannelData)[0],
                count: Int(recording.frameLength)))
            XCTAssertEqual(Double(samples.count) / 16_000, fixture.audioSeconds, accuracy: 0.00001)
            try await service.setReplay(samples: samples, sampleRate: 16_000)
            let id = DictationID()
            let began = clock.now()
            await observations.begin(id, at: began)
            let started = await service.startRecording(.init(id: id, personalVocabulary: .init(entries: [])))
            guard case .success = started else { XCTFail("Failed to start \(fixture.id)"); return }
            try await service.waitForReplayCompletion()
            let release = clock.now()
            // Diagnostic completion allowance; this is not the application's watchdog or an M1 benchmark.
            let finalization = await service.stopRecordingAndFinalize(.init(id: id,
                deadline: release.advanced(by: .seconds(30))))
            let elapsed = Double(clock.now().nanoseconds - release.nanoseconds) / 1_000_000
            let partials = await observations.snapshot(releasedAt: release)
            let text: String
            let isFinal: Bool
            switch finalization {
            case .final(let raw): text = raw.text; isFinal = true
            case .failed: text = ""; isFinal = false
            }
            results.append(.init(id: fixture.id, reference: fixture.reference, transcript: text,
                audioSeconds: fixture.audioSeconds, finalizationMilliseconds: elapsed,
                replayReleaseMilliseconds: Double(release.nanoseconds - began.nanoseconds) / 1_000_000,
                partialCountBeforeRelease: partials.beforeRelease,
                firstPartialMilliseconds: partials.first, partialCount: partials.count, final: isFinal))
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
            try encoder.encode(results).write(to: output, options: .atomic)
            XCTAssertTrue(isFinal && !text.isEmpty, "No final transcript for \(fixture.id)")
        }
    }
}

private actor PublicSpeechObservations {
    let clock: UptimeMonotonicClock
    var id: DictationID?
    var began = MonotonicInstant.zero
    var first: Double?
    var timestamps: [Int64] = []
    init(clock: UptimeMonotonicClock) { self.clock = clock }
    func begin(_ id: DictationID, at instant: MonotonicInstant) {
        self.id = id; began = instant; first = nil; timestamps.removeAll()
    }
    func receive(_ event: DictationEvent) {
        guard case .recognitionHypothesis(let eventID, _) = event, eventID == id else { return }
        let received = clock.now().nanoseconds
        if first == nil { first = Double(received - began.nanoseconds) / 1_000_000 }
        timestamps.append(received)
    }
    func snapshot(releasedAt release: MonotonicInstant) -> (first: Double?, count: Int, beforeRelease: Int) {
        (first, timestamps.count, timestamps.filter { $0 < release.nanoseconds }.count)
    }
}

